<template>
  <div class="space-y-4 min-w-0">
    <p v-if="error" class="alert-error" role="alert">{{ error }}<button class="text-link ml-2" @click="load">重新读取</button></p>
    <section class="section-panel p-4"><div class="flex flex-wrap justify-between gap-3"><div><h2 class="font-semibold">应用接入向导</h2><p class="mt-2 text-sm leading-6 text-surface-400">逐步配置健康目标、业务恢复、告警通知与修复权限。保存后仍需审阅提交；自动修复默认关闭。</p></div><button class="btn-primary" :disabled="busy || !targets.length" @click="startNew">接入一个应用</button></div></section>
    <section v-if="draft" class="section-panel p-4 sm:p-5 space-y-5">
      <nav class="flex flex-wrap gap-2" aria-label="应用接入步骤"><button v-for="(label, index) in steps" :key="label" class="btn-secondary btn-sm" :disabled="busy || index > unlocked" :aria-current="step === index ? 'step' : undefined" @click="step = index">{{ index + 1 }}. {{ label }}</button></nav>
      <p v-if="formError" class="alert-error" role="alert">{{ formError }}</p>
      <template v-if="step === 0"><label class="form-grid-label"><span>应用与节点</span><select v-model="targetKey" class="input w-full" :disabled="busy || !!saved" @change="choose"><option value="" disabled>选择纳管应用</option><option v-for="target in targets" :key="target.hostId + ':' + target.projectId" :value="target.hostId + ':' + target.projectId">{{ target.projectName }} · {{ target.hostId }}</option></select></label><p v-if="contextLoading" class="text-sm text-surface-400">读取此应用已配置能力…</p><div v-if="context" class="grid gap-3 sm:grid-cols-2"><p class="text-sm">健康目标：{{ context.profiles.length ? '已配置 ' + context.profiles.length + ' 个' : '待配置' }}</p><p class="text-sm">业务恢复：{{ context.recoveryPlans.length ? '已配置 ' + context.recoveryPlans.length + ' 个' : context.recovery.supported ? '待配置' : '不支持' }}</p><p class="text-sm">外部通知：{{ context.notifications.ready ? '已有启用渠道' : '待配置' }}</p><p class="text-sm">自动修复：默认不授权</p></div><p v-if="context" class="text-xs leading-6 text-surface-400">{{ context.recovery.limitations }}</p></template>
      <fieldset v-else-if="step === 1" :disabled="busy || completed('health')" class="space-y-4"><legend class="font-semibold mb-3">健康目标</legend><label class="form-grid-label"><span>配置方式</span><select v-model="draft.health.mode" class="input w-full" @change="chooseHealth"><option value="create">创建新的健康目标</option><option v-if="context?.profiles.some(row => row.enabled)" value="existing">使用现有目标</option></select></label><label v-if="draft.health.mode === 'existing'" class="form-grid-label"><span>已有目标</span><select v-model="draft.health.id" class="input w-full" @change="chooseHealth"><option v-for="profile in context?.profiles.filter(row => row.enabled)" :key="profile.id" :value="profile.id">{{ profile.serviceName }} · {{ profile.config.url }}</option></select></label><template v-else><label class="form-grid-label"><span>服务</span><select v-model="draft.health.serviceName" class="input w-full"><option v-for="service in context?.services" :key="service" :value="service">{{ service }}</option></select></label><label class="form-grid-label"><span>HTTP 健康地址</span><input v-model.trim="draft.health.config.url" class="input w-full" type="url" placeholder="https://app.example/health" /></label><div class="grid gap-3 sm:grid-cols-2"><label class="form-grid-label"><span>可用性目标（%）</span><input v-model.number="draft.health.config.targetPercent" class="input w-full" type="number" min="90" max="100" step="0.01" /></label><label class="form-grid-label"><span>响应延迟（毫秒）</span><input v-model.number="draft.health.config.maxLatencyMs" class="input w-full" type="number" min="50" max="10000" /></label></div></template><p class="text-xs leading-6 text-surface-400">从 ComposeOps 网络发起只读 HTTP 探针；无凭据、查询参数和重定向。详细超时与窗口可在应用目标页继续编辑。</p></fieldset>
      <fieldset v-else-if="step === 2" :disabled="busy || completed('recovery')" class="space-y-4"><legend class="font-semibold mb-3">备份与业务恢复</legend><label class="form-grid-label"><span>配置方式</span><select v-model="draft.recovery.mode" class="input w-full" @change="chooseRecovery"><option value="later">稍后配置并记录原因</option><option v-if="context?.recoveryPlans.some(row => row.enabled)" value="existing">使用已有业务恢复计划</option><option v-if="context?.recovery.supported" value="create">创建业务恢复计划</option></select></label><label v-if="draft.recovery.mode === 'later'" class="form-grid-label"><span>待配置原因</span><textarea v-model="draft.recovery.reason" class="input w-full" rows="2" minlength="4" maxlength="500" placeholder="例如：应用没有数据库，或恢复镜像尚未准备" /></label><label v-else-if="draft.recovery.mode === 'existing'" class="form-grid-label"><span>已有计划</span><select v-model="draft.recovery.id" class="input w-full" @change="chooseRecovery"><option v-for="plan in context?.recoveryPlans.filter(row => row.enabled)" :key="plan.id" :value="plan.id">{{ plan.config.dbService }} → {{ plan.config.appService }} · 版本 {{ plan.version }}</option></select></label><template v-else><BusinessRecoveryFields v-model="draft.recovery.config" :services="context?.services || []" /><label v-if="draft.recovery.config.engine !== 'postgres'" class="flex gap-2 text-sm"><input v-model="draft.recovery.noConcurrentDdl" type="checkbox" />确认备份窗口不执行数据库结构变更</label><label v-if="draft.recovery.config.scheduleHours" class="flex gap-2 text-sm"><input v-model="draft.recovery.scheduleApproved" type="checkbox" />授权定时备份和隔离业务演练（至少每 24 小时）</label></template><p class="text-xs leading-6 text-surface-400">接入向导保存恢复计划。手动备份与演练请到业务恢复页执行；启用定时计划后会按所选间隔运行。标记“稍后”不会显示为已完成灾备。</p></fieldset>
      <fieldset v-else-if="step === 3" :disabled="busy" class="space-y-4"><legend class="font-semibold mb-3">告警与通知</legend><label class="flex gap-2 text-sm"><input v-model="draft.alerts.enabled" type="checkbox" :disabled="completed('alerts')" />启用短长窗口联合错误预算告警</label><p class="text-xs leading-6 text-surface-400">快速告警：5 分钟与 60 分钟同时超过 14.4 倍消耗率；持续告警：30 分钟与 360 分钟同时超过 6 倍。最低覆盖率 90%，连续恢复 5 分钟后关闭告警。可在可靠性告警页调整。</p><label class="form-grid-label"><span>通知渠道</span><select v-model="draft.notifications" class="input w-full" :disabled="completed('notifications')"><option value="later">稍后配置，先在面板查看告警</option><option value="existing" :disabled="!context?.notifications.ready">使用已启用的全局通知渠道</option></select></label><p class="text-sm">{{ context?.notifications.ready ? '已启用：' + context.notifications.channels.map(row => row.type).join('、') : '尚无启用的外部通知渠道' }}</p><router-link to="/settings?tab=notifications" class="text-link text-sm">前往通知设置</router-link></fieldset>
      <fieldset v-else-if="step === 4" :disabled="busy || completed('autonomy')" class="space-y-4"><legend class="font-semibold mb-3">修复权限</legend><label class="flex items-start gap-2 text-sm"><input v-model="draft.autonomy.enabled" type="checkbox" /><span>对本应用目标启用有界自动重启</span></label><p class="text-sm leading-6 text-surface-400">默认仅观测与建议。启用后仅允许在持续故障时重启单副本服务；每个故障最多一次，结果未知即停止，拒绝策略仍生效。会造成短暂中断。</p><div v-if="draft.autonomy.enabled" class="grid gap-3 sm:grid-cols-3"><label class="form-grid-label"><span>有效天数</span><input v-model.number="draft.autonomy.days" class="input w-full" type="number" min="1" max="30" /></label><label class="form-grid-label"><span>每天最多次数</span><input v-model.number="draft.autonomy.maxDaily" class="input w-full" type="number" min="1" max="10" /></label><label class="form-grid-label"><span>冷却分钟</span><input v-model.number="draft.autonomy.cooldownMinutes" class="input w-full" type="number" min="5" max="1440" /></label></div></fieldset>
      <template v-else><h3 class="font-semibold">审阅接入配置</h3><p class="text-sm">{{ context?.projectName || saved?.projectName }} · {{ saved?.hostId || selected?.hostId }}</p><dl class="grid gap-3 text-sm sm:grid-cols-2"><div><dt class="text-surface-400">健康目标</dt><dd>{{ draft.health.mode === 'existing' ? '使用现有配置' : draft.health.serviceName + ' · ' + draft.health.config.url }}</dd></div><div><dt class="text-surface-400">业务恢复</dt><dd>{{ draft.recovery.mode === 'later' ? '待配置：' + draft.recovery.reason : draft.recovery.mode === 'existing' ? '关联现有计划' : '创建固定目标与业务断言' }}</dd></div><div><dt class="text-surface-400">告警</dt><dd>{{ draft.alerts.enabled ? '启用联合窗口告警' : '关闭' }}</dd></div><div><dt class="text-surface-400">通知</dt><dd>{{ draft.notifications === 'existing' ? '使用已启用渠道' : '待配置，仅在面板显示' }}</dd></div><div><dt class="text-surface-400">自动修复</dt><dd>{{ draft.autonomy.enabled ? '拟授权，每天最多 ' + draft.autonomy.maxDaily + ' 次' : '关闭' }}</dd></div></dl><p v-if="saved?.error" class="alert-error">{{ saved.error }}</p><p v-for="(result, key) in visibleProgress" :key="key" class="text-xs">{{ progressLabel(key) }}：{{ result.status === 'configured' ? '已配置' : '待配置' }} {{ result.reason || '' }}</p><label v-if="draft.autonomy.enabled" class="flex items-start gap-2 text-sm"><input v-model="autonomyApproved" type="checkbox" :disabled="busy" /><span>明确授权上述次数、冷却和期限内的自动重启。</span></label><div class="flex flex-wrap gap-2"><button class="btn-secondary" :disabled="busy" @click="saveDraft">保存草稿</button><button class="btn-primary" :disabled="busy || draft.autonomy.enabled && !autonomyApproved" @click="submit">{{ saved?.status === 'partial' ? '恢复未完成步骤' : '确认配置并接入' }}</button></div></template>
      <div class="flex flex-wrap justify-between gap-2 border-t border-surface-800 pt-4"><button class="btn-secondary" :disabled="busy" @click="draft = null; saved = null; context = null">关闭向导</button><div class="flex gap-2"><button v-if="step > 0" class="btn-secondary" :disabled="busy" @click="step--">上一步</button><button v-if="step < 5" class="btn-primary" :disabled="busy || !context || contextLoading" @click="next">下一步</button></div></div>
    </section>
    <section v-for="item in drafts" :key="item.id" class="section-panel p-4"><div class="flex flex-wrap justify-between gap-2"><h3 class="font-semibold">{{ item.projectName }} · {{ item.hostId }}</h3><span class="text-sm">{{ item.status === 'complete' ? '接入配置已提交' : item.status === 'partial' ? '部分提交，可恢复' : item.status === 'applying' ? '正在提交' : '已保存草稿' }}</span></div><p v-if="item.error" class="mt-2 text-xs text-status-warn">{{ item.error }}</p><p v-for="(result, key) in progressOf(item)" :key="key" class="mt-2 text-xs">{{ progressLabel(key) }}：{{ result.status === 'configured' ? '已配置' : '待配置' }} {{ result.reason || '' }}</p><p v-if="item.status === 'complete'" class="mt-3 text-xs text-surface-400">仍标记待配置的能力尚未接入，可在对应功能页继续。配置提交不等于业务恢复或告警已经验收。</p><div class="mt-3 flex flex-wrap gap-2"><button v-if="['draft', 'partial'].includes(item.status)" class="btn-secondary btn-sm" :disabled="busy" @click="resume(item)">继续配置</button><router-link v-if="item.status === 'complete'" to="/reliability?tab=targets" class="btn-secondary btn-sm">编辑健康与授权</router-link><router-link v-if="item.status === 'complete'" to="/reliability?tab=business" class="btn-secondary btn-sm">业务恢复设置</router-link></div></section>
  </div>
</template>
<script setup>
import { ref, computed, toRaw, onMounted, onActivated, onDeactivated, onBeforeUnmount } from 'vue';
import { api } from '../api/client.js';
import BusinessRecoveryFields from './BusinessRecoveryFields.vue';
const steps = ['选择应用', '健康目标', '业务恢复', '告警通知', '修复权限', '审阅提交'];
const targets = ref([]), drafts = ref([]), draft = ref(null), saved = ref(null), context = ref(null), targetKey = ref(''), step = ref(0), unlocked = ref(0), busy = ref(false), error = ref(''), formError = ref(''), autonomyApproved = ref(false), contextLoading = ref(false);
const selected = computed(() => targets.value.find(row => row.hostId + ':' + row.projectId === targetKey.value));
const progressOf = value => Object.fromEntries(Object.entries(value?.progress || {}).filter(([_key, row]) => row.status));
const visibleProgress = computed(() => progressOf(saved.value));
const completed = key => saved.value?.progress[key]?.status === 'configured';
const progressLabel = key => ({ health: '健康目标', recovery: '业务恢复', alerts: '告警规则', notifications: '外部通知', autonomy: '修复权限' })[key] || key;
let active = false, disposed = false, epoch = 0, loading = false, controller, contextController, contextEpoch = 0, requestId = '';
const clone = value => JSON.parse(JSON.stringify(toRaw(value)));
const defaultConfig = () => ({ health: { mode: 'create', serviceName: '', config: { url: '', targetPercent: 99.9, maxLatencyMs: 1000 } }, recovery: { mode: 'later', reason: '' },
  alerts: { enabled: true, minimumCoverage: 0.9, maintenanceUntil: 0, fast: { shortMinutes: 5, longMinutes: 60, burnRate: 14.4 }, slow: { shortMinutes: 30, longMinutes: 360, burnRate: 6 }, recoverMinutes: 5 }, notifications: 'later', autonomy: { enabled: false, days: 7, maxDaily: 1, cooldownMinutes: 30 } });
async function load() {
  if (!active || loading || busy.value) return; const current = ++epoch; loading = true; controller = new AbortController();
  try { const [data, projects] = await Promise.all([api.getSreResource('onboarding', controller.signal), api.getSreTargets(controller.signal)]); if (active && current === epoch) { drafts.value = data.drafts; targets.value = projects.targets; error.value = ''; } }
  catch (cause) { if (active && current === epoch) error.value = cause.message; }
  finally { if (current === epoch) loading = false; }
}
function startNew() { draft.value = defaultConfig(); saved.value = null; context.value = null; targetKey.value = ''; step.value = 0; unlocked.value = 0; formError.value = ''; autonomyApproved.value = false; requestId = crypto.randomUUID(); }
async function readContext(hostId, projectId) {
  contextController?.abort(); const current = ++contextEpoch; contextController = new AbortController(); contextLoading.value = true;
  try { const result = await api.getSreResource('onboarding/context?' + new URLSearchParams({ hostId, projectId }), contextController.signal); if (active && current === contextEpoch) { context.value = result; formError.value = ''; return result; } }
  catch (cause) { if (active && current === contextEpoch) formError.value = cause.message; }
  finally { if (current === contextEpoch) contextLoading.value = false; }
}
async function choose() {
  context.value = null; if (!selected.value) return; draft.value = defaultConfig(); unlocked.value = 0; const result = await readContext(selected.value.hostId, selected.value.projectId);
  if (!result || !draft.value) return; const profile = result.profiles.find(row => row.enabled);
  draft.value.health = profile ? { mode: 'existing', id: profile.id, version: profile.version } : { ...draft.value.health, serviceName: result.services[0] || '' };
  if (result.notifications.ready) draft.value.notifications = 'existing';
}
function chooseHealth() {
  if (draft.value.health.mode === 'existing') { const profile = context.value.profiles.find(row => row.id === draft.value.health.id) || context.value.profiles.find(row => row.enabled); draft.value.health = { mode: 'existing', id: profile.id, version: profile.version }; }
  else draft.value.health = { mode: 'create', serviceName: context.value.services[0], config: { url: '', targetPercent: 99.9, maxLatencyMs: 1000 } };
}
function chooseRecovery() {
  const value = draft.value.recovery;
  if (value.mode === 'existing') { const plan = context.value.recoveryPlans.find(row => row.id === value.id) || context.value.recoveryPlans.find(row => row.enabled); draft.value.recovery = { mode: 'existing', id: plan.id, version: plan.version }; }
  if (value.mode === 'create') draft.value.recovery = { mode: 'create', noConcurrentDdl: false, scheduleApproved: false, config: { engine: 'postgres', dbService: '', appService: '', database: '', user: 'postgres', credentialEnv: 'POSTGRES_PASSWORD', appEnvironment: { DATABASE_URL: '$DB_URL' }, assertions: [{ table: '', expectedRows: 1, column: '', equals: '' }], http: { port: 8080, path: '/health', expectedStatus: 200, bodyContains: '' }, rpoMinutes: 1440, rtoMinutes: 15, scheduleHours: 0 } };
  if (value.mode === 'later') draft.value.recovery = { mode: 'later', reason: '' };
}
function next() {
  formError.value = '';
  if (step.value === 1 && draft.value.health.mode === 'create' && !/^https?:\/\//.test(draft.value.health.config.url)) { formError.value = '请填写完整健康检查地址'; return; }
  if (step.value === 2 && draft.value.recovery.mode === 'later' && String(draft.value.recovery.reason || '').trim().length < 4) { formError.value = '请记录稍后配置业务恢复的原因'; return; }
  step.value++; unlocked.value = Math.max(unlocked.value, step.value);
}
async function resume(item) { saved.value = clone(item); draft.value = clone(item.config); targetKey.value = item.hostId + ':' + item.projectId; context.value = null; step.value = 5; unlocked.value = 5; formError.value = ''; autonomyApproved.value = false; await readContext(item.hostId, item.projectId); }
async function persistDraft() {
  const body = { hostId: saved.value?.hostId || selected.value.hostId, projectId: saved.value?.projectId || selected.value.projectId, config: clone(draft.value), ...(saved.value ? { version: saved.value.version } : { requestId }) };
  return (await api.sreOperation('onboarding' + (saved.value ? '/' + saved.value.id : ''), body, saved.value ? 'PUT' : 'POST')).draft;
}
async function action(apply) {
  if (!active || busy.value) return; controller?.abort(); epoch++; loading = false; const current = epoch; busy.value = true; formError.value = '';
  try {
    const record = await persistDraft(); if (!active || current !== epoch) return; saved.value = record; draft.value = clone(record.config);
    if (apply) {
      const result = await api.sreOperation('onboarding/' + record.id + '/apply', { version: record.version, fingerprint: record.fingerprint, confirm: 'APPLY_APPLICATION_ONBOARDING', ...(record.config.autonomy.enabled && autonomyApproved.value ? { autonomyConfirm: 'ENABLE_AUTONOMY' } : {}) });
      if (!active || current !== epoch) return; saved.value = result.draft;
      if (result.draft.status === 'complete') { draft.value = null; saved.value = null; } else formError.value = result.draft.error;
    }
  } catch (cause) { if (active && current === epoch) formError.value = cause.message; }
  finally { busy.value = false; if (active && current === epoch) void load(); }
}
function saveDraft() { return action(false); }
function submit() { if (draft.value.autonomy.enabled && !autonomyApproved.value) { formError.value = '请单独确认自动重启授权'; return; } return action(true); }
function start() { if (active || disposed) return; active = true; void load(); const target = saved.value || selected.value; if (draft.value && target) void readContext(target.hostId, target.projectId); }
function stop() { active = false; controller?.abort(); contextController?.abort(); epoch++; contextEpoch++; loading = false; contextLoading.value = false; }
onMounted(start); onActivated(start); onDeactivated(stop); onBeforeUnmount(() => { disposed = true; stop(); });
</script>
